def cnot(control, target):
    """Implement CNOT gate operation on binary level"""
    control_bits = format(ord(control), '08b')
    target_bits = format(ord(target), '08b')
    result = ''

    # Apply CNOT bit by bit
    for c, t in zip(control_bits, target_bits):
        if c == '1':
            # XOR operation when control bit is 1
            result += '1' if t == '0' else '0'
        else:
            # Keep target bit unchanged when control bit is 0
            result += t

    return chr(int(result, 2))

