from pwn import *
import itertools

def apply_cnot(control_bit, target_bit):
    """Apply CNOT operation on single bits"""
    if control_bit == '1':
        return '1' if target_bit == '0' else '0'
    return target_bit

def cnot_char(control, target):
    """Apply CNOT operation on character level"""
    control_bits = format(ord(control), '08b')
    target_bits = format(ord(target), '08b')
    result = ''
    for c, t in zip(control_bits, target_bits):
        result += apply_cnot(c, t)
    return chr(int(result, 2))

def process_sequence(data, control_indices):
    """Process a sequence of characters using given control indices"""
    result = list(data)
    for i in range(len(data)):
        if i not in control_indices:
            # Find the closest control bit before and after
            before = max((x for x in control_indices if x < i), default=None)
            after = min((x for x in control_indices if x > i), default=None)

            if before is not None:
                result[i] = cnot_char(data[before], result[i])
            if after is not None:
                result[i] = cnot_char(data[after], result[i])

    return ''.join(result)

