    # Find positions of control characters
    dollar_pos = find_control_positions(ciphertext, '$')
    z_pos = find_control_positions(ciphertext, 'Z')

    # Try applying CNOT operations in different orders
    def recursive_apply(text, depth=0, max_depth=4):
        if depth >= max_depth:
            return

        # Apply $ controls
        for pos in dollar_pos:
            # Try forward CNOT
            if pos + 2 < len(text):
                new_text = apply_cnot(text, pos, pos + 2)
                results.add(new_text)
                recursive_apply(new_text, depth + 1, max_depth)

            # Try backward CNOT
            if pos - 2 >= 0:
                new_text = apply_cnot(text, pos, pos - 2)
                results.add(new_text)
                recursive_apply(new_text, depth + 1, max_depth)

        # Apply Z controls
        for pos in z_pos:
            # Try forward CNOT
