                control_bits = text[i]
                for pos in range(8):
                    if (control_bits >> pos) & 1:
                        # Flip the target bit in next position
                        target_pos = (pos + 1) % 8
                        result[i + 1] ^= (1 << target_pos)

    # Second pass: handle Z controls (backward direction)
    for i in range(length - 1, -1, -1):
        if chr(text[i]) == 'Z':
            if i > 0:
                # Z controls the previous character: flip bits based on control bits
                control_bits = text[i]
                for pos in range(8):
                    if (control_bits >> pos) & 1:
                        # Flip the target bit in previous position
                        target_pos = (pos - 1) % 8
                        result[i - 1] ^= (1 << target_pos)

    return bytes(result)

